"""
PhotoToCode AI Backend - 100% Uncensored, Free HuggingFace Space
Supports both:
1. REST API for Next.js / Vercel frontend (GET /ping, POST /analyze)
2. Interactive Gradio UI on HuggingFace Space
"""

import os
import io
import re
import json
import base64
import numpy as np
from PIL import Image
import easyocr
from colorthief import ColorThief

import fastapi
from fastapi import FastAPI, Request
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
import gradio as gr

# Initialize FastAPI
app = FastAPI(title="PhotoToCode AI Backend", version="2.0.0")

# Setup CORS - Allow all origins for Vercel frontend
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["*"],
    allow_headers=["*"],
)

# Global OCR Reader (English + Bengali support)
print("Initializing EasyOCR Reader...")
try:
    reader = easyocr.Reader(['en', 'bn'], gpu=False)
except Exception as e:
    print(f"Fallback to English OCR: {e}")
    reader = easyocr.Reader(['en'], gpu=False)

def rgb_to_hex(rgb):
    return "#{:02x}{:02x}{:02x}".format(int(rgb[0]), int(rgb[1]), int(rgb[2]))

def extract_colors(img_pil):
    try:
        buf = io.BytesIO()
        img_pil.save(buf, format="JPEG")
        buf.seek(0)
        ct = ColorThief(buf)
        dom = rgb_to_hex(ct.get_color(quality=5))
        pal = [rgb_to_hex(c) for c in ct.get_palette(color_count=6, quality=5)]
        return dom, pal
    except Exception:
        return "#ffffff", ["#000000", "#ffffff", "#333333", "#666666", "#f0f0f0"]

def build_pixel_perfect_html(ocr_items, width, height, bg_color, palette):
    html_elements = []
    sorted_items = sorted(ocr_items, key=lambda it: it["box"][1])

    for item in sorted_items:
        x, y, w, h = item["box"]
        text = item["text"].strip()
        idx = item["id"]
        font_size = max(10, int(h * 0.72))
        text_color = "#111827" if bg_color.lower() in ["#ffffff", "#fafafa", "#f5f5f5"] else "#f3f4f6"
        is_bold = h > 30 or font_size > 18
        font_weight = "700" if is_bold else "400"

        elem_html = f'''  <div id="el-{idx}" class="figma-element" data-id="{idx}" style="
    position: absolute;
    left: {x}px;
    top: {y}px;
    width: {w}px;
    min-height: {h}px;
    font-size: {font_size}px;
    font-weight: {font_weight};
    color: {text_color};
    line-height: 1.2;
    display: flex;
    align-items: center;
    box-sizing: border-box;
    cursor: pointer;
    font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
  ">{text}</div>'''
        html_elements.append(elem_html)

    body_content = "\n".join(html_elements)

    full_html = f'''<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>PhotoToCode Figma Clone</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    * {{
      margin: 0;
      padding: 0;
      box-sizing: border-box;
    }}
    body {{
      background: {bg_color};
      font-family: 'Inter', -apple-system, BlinkMacSystemFont, sans-serif;
      overflow-x: auto;
      min-height: 100vh;
      position: relative;
    }}
    .figma-canvas {{
      position: relative;
      width: {width}px;
      height: {height}px;
      background: {bg_color};
      margin: 0 auto;
      overflow: hidden;
    }}
    .figma-element:hover {{
      outline: 2px solid #8b5cf6;
      outline-offset: 1px;
    }}
  </style>
</head>
<body>
  <div class="figma-canvas">
{body_content}
  </div>
</body>
</html>'''
    return full_html

def process_image(img_pil):
    width, height = img_pil.size
    img_np = np.array(img_pil)
    raw_ocr = reader.readtext(img_np)

    ocr_items = []
    for idx, (bbox, text, conf) in enumerate(raw_ocr):
        if not text.strip():
            continue
        xs = [pt[0] for pt in bbox]
        ys = [pt[1] for pt in bbox]
        x = max(0, int(min(xs)))
        y = max(0, int(min(ys)))
        w = max(10, int(max(xs) - min(xs)))
        h = max(10, int(max(ys) - min(ys)))

        ocr_items.append({
            "id": idx,
            "text": text.strip(),
            "box": [x, y, w, h],
            "confidence": round(float(conf), 2)
        })

    dom_color, palette = extract_colors(img_pil)
    html_code = build_pixel_perfect_html(ocr_items, width, height, dom_color, palette)

    return {
        "success": True,
        "status": "success",
        "html": html_code,
        "generatedHTML": html_code,
        "generated_html": html_code,
        "texts": ocr_items,
        "width": width,
        "height": height,
        "canvas": {"width": width, "height": height},
        "dominantColor": dom_color,
        "palette": palette,
        "colors": {
            "dominant": dom_color,
            "palette": palette
        }
    }

@app.get("/ping")
async def ping():
    return {"pong": True, "status": "ok", "service": "PhotoToCode HuggingFace AI", "uncensored": True}

@app.options("/analyze")
async def options_analyze():
    return JSONResponse(content={"status": "ok"}, headers={"Access-Control-Allow-Origin": "*", "Access-Control-Allow-Methods": "POST, GET, OPTIONS", "Access-Control-Allow-Headers": "*"})

@app.post("/analyze")
async def api_analyze(req: Request):
    try:
        body = await req.json()
        raw_b64 = body.get("image", "")
        if not raw_b64:
            return JSONResponse(status_code=400, content={"error": "No image provided"})
        if "base64," in raw_b64:
            raw_b64 = raw_b64.split("base64,")[1]
        img_bytes = base64.b64decode(raw_b64)
        img = Image.open(io.BytesIO(img_bytes)).convert("RGB")
        result = process_image(img)
        return JSONResponse(content=result, headers={"Access-Control-Allow-Origin": "*"})
    except Exception as e:
        return JSONResponse(status_code=500, content={"error": str(e)}, headers={"Access-Control-Allow-Origin": "*"})

def gradio_predict(input_image):
    if input_image is None:
        return "Please upload an image.", ""
    img_pil = Image.fromarray(input_image)
    res = process_image(img_pil)
    return res["html"], json.dumps(res["texts"], indent=2, ensure_ascii=False)

with gr.Blocks(title="PhotoToCode AI Backend") as demo:
    gr.Markdown("# 🎨 PhotoToCode AI - Uncensored Backend")
    with gr.Row():
        with gr.Column():
            in_img = gr.Image(label="Upload Image", type="numpy")
            btn = gr.Button("⚡ Convert to HTML Code", variant="primary")
        with gr.Column():
            out_html = gr.Code(label="Generated Pixel-Exact HTML/CSS", language="html")
            out_json = gr.Code(label="Extracted Text Elements", language="json")
    btn.click(gradio_predict, inputs=[in_img], outputs=[out_html, out_json])

app = gr.mount_gradio_app(app, demo, path="/")

if __name__ == "__main__":
    import uvicorn
    uvicorn.run(app, host="0.0.0.0", port=7860)
